/// <summary>
/// Call enableFields after the run method instead of init so it can also show Invoice consolidation by rebate type and vendor account for TAMRebateDealListPageVendRebate when creating new deal
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormEventHandler(formStr(TAMRebateDealNewDeal), FormEventType::PostRun),
 SuppressBPWarning('BPParameterNotUsed', '@MET:BPParameterNotUsedMessage')]
public static void TAMRebateDealNewDeal_OnPostRun(xFormRun sender, FormEventArgs e)
{
    FormRun formRun = sender;

    const str enableFields = 'enableFields';

    if (SysFormRun::hasMethod(formRun, identifierStr(enableFields)))
    {
        formRun.enableFields();
    }
}
